import java.util.HashMap;
import java.util.Map;

Map result = new HashMap();
String gecos = account.getStringAttribute("gecos");
if (gecos != null) {
    String[] parts = gecos.split(",", -1);
    if (parts.length > 1) {
        String candidate = parts[1].trim().toUpperCase();
        if (candidate.matches("^[A-Z]?[0-9]{5,8}$")) {
            result.put("identityAttributeName", "employeeId");
            result.put("identityAttributeValue", candidate);
            return result;
        }
    }
}
String name = account.getIdentity();
if (name != null && !name.equals("root") && account.getIntAttribute("uid") >= 1000) {
    result.put("identityAttributeName", "linuxLogin");
    result.put("identityAttributeValue", name.toLowerCase());
}
return result;
